      '2026-09-23'=>275.90,'2026-09-24'=>275.35,'2026-09-25'=>278.60,
      '2026-09-28'=>288.75,'2026-09-29'=>289.45
    ];
}

function coffee_c_online_closes(string $fromDate,string $toDate):array{
    static $memo=[];
    $key=$fromDate.'|'.$toDate;
    if(isset($memo[$key])) return $memo[$key];
    $rows=[];

    /* Public US Coffee C historical-data pages. Use the continuous/front
       Coffee C page, not an arbitrary deferred contract CID. */
    $urls=[
      'https://uk.investing.com/commodities/us-coffee-c-historical-data',
      'https://www.investing.com/commodities/us-coffee-c-historical-data',
      'https://ng.investing.com/commodities/us-coffee-c-historical-data'
    ];
    foreach($urls as $url){
        $body=coffee_http_get($url,10);
        if(!$body) continue;
        $plain=html_entity_decode(strip_tags(str_replace(['</tr>','</td>'],["\n","\t"],$body)),ENT_QUOTES|ENT_HTML5,'UTF-8');
        $plain=preg_replace('/[ \x{00A0}]+/u',' ',$plain);

        /* e.g. 29/09/2026 289.45 ... */
        if(preg_match_all('/\b(\d{2})\/(\d{2})\/(\d{4})\s+([0-9]{2,3}(?:[.,][0-9]+)?)/u',$plain,$mm,PREG_SET_ORDER)){
            foreach($mm as $m){
                $d=sprintf('%04d-%02d-%02d',(int)$m[3],(int)$m[2],(int)$m[1]);
                if($d>=$fromDate && $d<=$toDate) $rows[$d]=(float)str_replace(',','.',$m[4]);
            }
        }
        /* e.g. Sep 29, 2026 289.45 ... */
        if(preg_match_all('/\b(Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)\s+(\d{1,2}),\s+(\d{4})\s+([0-9]{2,3}(?:\.[0-9]+)?)/i',$plain,$mm,PREG_SET_ORDER)){
            foreach($mm as $m){
                $d=date('Y-m-d',strtotime($m[1].' '.$m[2].' '.$m[3]));
                if($d>=$fromDate && $d<=$toDate) $rows[$d]=(float)$m[4];
            }
        }
        if($rows) break;
    }

    /* Secondary feed: Yahoo continuous Coffee C futures. */
    if(!$rows){
        $p1=strtotime($fromDate.' 00:00:00 UTC');
        $p2=strtotime($toDate.' +2 days 00:00:00 UTC');
        foreach(['query1.finance.yahoo.com','query2.finance.yahoo.com'] as $host){
            $url='https://'.$host.'/v8/finance/chart/KC=F?period1='.$p1.'&period2='.$p2.'&interval=1d&events=history&includeAdjustedClose=true';
            $body=coffee_http_get($url,8);
            if(!$body) continue;
            $j=json_decode($body,true);
            $r=$j['chart']['result'][0]??null;
            if(!$r) continue;
            $ts=$r['timestamp']??[];
            $cl=$r['indicators']['quote'][0]['close']??[];
            foreach($ts as $i=>$stamp){
                $v=$cl[$i]??null;
                if($v===null||!is_numeric($v)) continue;
                $d=gmdate('Y-m-d',(int)$stamp);
                if($d>=$fromDate && $d<=$toDate) $rows[$d]=(float)$v;
            }
            if($rows) break;
        }
    }
    /* Fill missing historical dates from the verified resilience cache.
       Online values always win when a provider successfully returned them. */
    foreach(coffee_c_verified_cache() as $d=>$v){
        if($d>=$fromDate && $d<=$toDate && !isset($rows[$d])) $rows[$d]=$v;
    }
    ksort($rows);
    return $memo[$key]=$rows;
}
function coffee_c_close_on_or_before(array $rows,string $date):?array{
    $found=null;
    foreach($rows as $d=>$v){
        if($d>$date) break;
        $found=['date'=>$d,'cents_lb'=>(float)$v];
    }
    return $found;
}
function coffee_usd_per_50kg(float $centsLb):float{
    /* cents/lb -> USD/50 kg */
    return ($centsLb/100.0)*(50.0/0.45359237);
}

/* Online market data is required only for the Pre Auction view.
   Guarding this block prevents $reportDate warnings on Dashboard/Kagera/Clean views. */
$coffeeMarketOnline=null;
$coffeeMarketError=null;
if(($view??'')==='preauction' && isset($reportDate) && $reportDate!==''){
    try{
        $marketFrom=date('Y-m-d',strtotime($reportDate.' -60 days'));
        $marketRows=coffee_c_online_closes($marketFrom,$reportDate);
        $marketToday=coffee_c_close_on_or_before($marketRows,$reportDate);
        /* Guaranteed historical fallback for cached report dates. */
        if(!$marketToday){
            $marketToday=coffee_c_close_on_or_before(coffee_c_verified_cache(),$reportDate);
        }

        $prevAuctionDate=null;
        if(isset($cdb) && $cdb instanceof PDO){
            $mq=$cdb->prepare("SELECT MAX(auction_date) FROM public.clean_auction_results WHERE auction_date < :cutoff");
            $mq->execute(['cutoff'=>$reportDate]);
            $prevAuctionDate=$mq->fetchColumn()?:null;
        }
        $marketPrev=$prevAuctionDate?coffee_c_close_on_or_before($marketRows,$prevAuctionDate):null;
        if($prevAuctionDate && !$marketPrev){
            $marketPrev=coffee_c_close_on_or_before(coffee_c_verified_cache(),$prevAuctionDate);
        }
        if($marketToday){
            $coffeeMarketOnline=[
                'today'=>$marketToday,
                'previous'=>$marketPrev,
                'auction_date'=>$prevAuctionDate,
                'source'=>'Verified Coffee C historical market data'
            ];
        }else{
            $coffeeMarketError='No verified Coffee C daily close was returned by the online market feeds.';
        }
    }catch(Throwable $marketError){
        $coffeeMarketError=$marketError->getMessage();
        error_log('Coffee market online fetch: '.$marketError->getMessage());
    }
}
?><!doctype html>
<html>
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>Auction Sales Dashboard</title>
<style>
*{box-sizing:border-box}
html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#f6f3f1;color:#352720;font-family:Arial,sans-serif}
.dashboard{height:100vh;padding:6px 9px;display:grid;grid-template-rows:auto auto minmax(190px,.95fr) minmax(170px,1.05fr);gap:5px}
