 .pre-paper{padding:10px 6px}
}


/* =========================================================
   DASHBOARD HEADER / DISPLAY CONTROLS — RESPONSIVE ALL VIEWS
   ========================================================= */
.dashboard .topbar{
  width:100%!important;
  max-width:none!important;
  min-width:0!important;
  box-sizing:border-box!important;
  display:flex!important;
  align-items:center!important;
  justify-content:space-between!important;
  gap:10px!important;
}
.dashboard .topbar .title{
  flex:0 1 auto!important;
  min-width:0!important;
}
.dashboard .dashboard-view-controls,
.dashboard .topbar form{
  margin-left:auto!important;
  min-width:0!important;
  max-width:100%!important;
  display:flex!important;
  flex-direction:row!important;
  align-items:center!important;
  justify-content:flex-end!important;
  flex-wrap:wrap!important;
  gap:5px 7px!important;
  box-sizing:border-box!important;
}
.dashboard .dashboard-view-controls label,
.dashboard .topbar form label{
  flex:0 0 auto!important;
  white-space:nowrap!important;
  margin:0!important;
}
.dashboard .dashboard-view-controls select,
.dashboard .topbar form select{
  width:auto!important;
  min-width:145px!important;
  max-width:260px!important;
  height:32px!important;
  padding:4px 28px 4px 8px!important;
  box-sizing:border-box!important;
  white-space:nowrap!important;
  text-overflow:ellipsis!important;
}

/* Report views must use exactly the same available content width as
   Kagera/Clean Auction. Do not constrain them to a pseudo-slide width. */
.dashboard:has(.sales-ppt),
.dashboard:has(.pre-report){
  width:100%!important;
  max-width:none!important;
  min-width:0!important;
}
.sales-ppt,.pre-report{
  width:100%!important;
  max-width:none!important;
  min-width:0!important;
  margin:0!important;
  box-sizing:border-box!important;
}
.pre-paper{
  width:100%!important;
  max-width:none!important;
  min-width:0!important;
  margin:0!important;
  box-sizing:border-box!important;
}
.sales-ppt-body{
  width:100%!important;
  max-width:none!important;
  min-width:0!important;
}
.sales-ppt .sales-meta,
.sales-ppt .sales-table{
  width:100%!important;
  max-width:100%!important;
}

/* Large screens: keep Season + Display compact on one professional row. */
@media(min-width:1100px){
  .dashboard .topbar{
    flex-wrap:nowrap!important;
  }
  .dashboard .dashboard-view-controls,
  .dashboard .topbar form{
    flex-wrap:nowrap!important;
  }
  .dashboard .dashboard-view-controls select[name="season"],
  .dashboard .topbar form select[name="season"]{
    min-width:125px!important;
    max-width:150px!important;
  }
  .dashboard .dashboard-view-controls select[name="display"],
  .dashboard .topbar form select[name="display"]{
    min-width:210px!important;
    max-width:245px!important;
  }
}

/* Medium screens: controls wrap as a unit rather than becoming a long
   concatenated Season/Display line. */
@media(max-width:1099px){
  .dashboard .topbar{
    align-items:flex-start!important;
    flex-wrap:wrap!important;
  }
  .dashboard .dashboard-view-controls,
  .dashboard .topbar form{
    flex:1 1 520px!important;
    justify-content:flex-end!important;
  }
}

/* Phones/tablets: readable two-column label/control layout. */
@media(max-width:700px){
  .dashboard .topbar{
    display:block!important;
  }
  .dashboard .topbar .title{
    width:100%!important;
    margin:0 0 6px!important;
  }
  .dashboard .dashboard-view-controls,
  .dashboard .topbar form{
    width:100%!important;
    display:grid!important;
    grid-template-columns:max-content minmax(0,1fr)!important;
    gap:5px 7px!important;
    margin:0!important;
  }
  .dashboard .dashboard-view-controls select,
  .dashboard .topbar form select{
    width:100%!important;
    min-width:0!important;
    max-width:none!important;
  }
  .sales-ppt,.pre-report,.pre-paper{
    width:100%!important;
    max-width:100%!important;
  }
}


/* PRE-AUCTION REPORT — content-aware responsive tables */
.pre-paper .pre-date-note{text-align:center;font-size:10px;font-style:italic;margin:-3px 0 8px;color:#66534b}
.pre-main-title{margin-top:4px;text-decoration:none;font-size:clamp(14px,2vw,18px);line-height:1.3}
.pre-paper table{table-layout:auto!important;width:100%!important;max-width:100%!important}
.pre-paper th,.pre-paper td{width:auto!important;max-width:none!important;vertical-align:middle}
.pre-paper th:first-child,.pre-paper td:first-child{width:1%;white-space:nowrap!important}
.pre-paper th:nth-child(2),.pre-paper td:nth-child(2){min-width:min(210px,32vw)}
.pre-paper td:not(:nth-child(2)),.pre-paper th:not(:nth-child(2)){white-space:nowrap!important}
.pre-paper .pre-scroll{max-width:100%;overflow-x:auto;scrollbar-width:thin}
.pre-paper .pre-scroll table{min-width:max-content!important}
.pre-paper .pre-farm-table th:nth-child(2),.pre-paper .pre-farm-table td:nth-child(2){min-width:min(260px,38vw);white-space:normal!important}
@media(min-width:900px){.pre-paper .pre-scroll table{min-width:100%!important}.pre-paper th,.pre-paper td{white-space:normal!important}.pre-paper th:first-child,.pre-paper td:first-child{white-space:nowrap!important}}
