<script src="https://cdn.jsdelivr.net/npm/jspdf@2.5.2/dist/jspdf.umd.min.js"></script>
<script src="https://cdn.jsdelivr.net/npm/jspdf-autotable@3.8.4/dist/jspdf.plugin.autotable.min.js"></script>
<script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.7/dist/chart.umd.min.js"></script>
<script>
(function(){
 const sel=document.getElementById('tcAnalysisType'),box=document.getElementById('tcAnalysisTable'),
 search=document.getElementById('tcPartySearch'),status=document.getElementById('tcAnalysisStatus'),
 exportBtn=document.getElementById('tcAnalysisExportBtn'),exportMenu=document.getElementById('tcAnalysisExportMenu');
 if(!sel||!box)return;
 const D=<?=json_encode($display==='totalclean'?$tcAnalytics:[],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)?>;
 const M={
  buyer_channel:{party:'buyer',dim:'channel',partyLabel:'Buyer',dimLabel:'Sales Channel'},
  supplier_channel:{party:'supplier',dim:'channel',partyLabel:'Supplier / Seller',dimLabel:'Sales Channel'},
  buyer_region:{party:'buyer',dim:'region',partyLabel:'Buyer',dimLabel:'Region'},
  supplier_region:{party:'supplier',dim:'region',partyLabel:'Supplier / Seller',dimLabel:'Region'},
  buyer_type:{party:'buyer',dim:'coffee_type',partyLabel:'Buyer',dimLabel:'Coffee Type'},
  supplier_type:{party:'supplier',dim:'coffee_type',partyLabel:'Supplier / Seller',dimLabel:'Coffee Type'}
 };
 const esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]));
 const fmt=(v,d=2)=>{v=Number(v)||0;return v.toLocaleString(undefined,{minimumFractionDigits:0,maximumFractionDigits:Number.isInteger(v)?0:Math.min(d,2)})};
 let expanded=false,current={};

 function build(){
  const cfg=M[sel.value], all=D[sel.value]||[], q=(search?.value||'').trim().toLowerCase();
  const partyTotals=new Map(),cells=new Map(),dimTotals=new Map();
  all.forEach(r=>{
   const p=r[cfg.party]||'Unspecified',d=r[cfg.dim]||'Unspecified',kg=+r.kgs||0,val=+r.value_usd||0;
   let x=partyTotals.get(p)||{kg:0,val:0};x.kg+=kg;x.val+=val;partyTotals.set(p,x);
   x=cells.get(p+'\x1f'+d)||{kg:0,val:0};x.kg+=kg;x.val+=val;cells.set(p+'\x1f'+d,x);
   x=dimTotals.get(d)||{kg:0,val:0};x.kg+=kg;x.val+=val;dimTotals.set(d,x);
  });
  const allParties=[...partyTotals.keys()].sort((a,b)=>partyTotals.get(b).kg-partyTotals.get(a).kg);
  const filtered=q?allParties.filter(p=>p.toLowerCase().includes(q)):allParties;
  const top=q?filtered:allParties.slice(0,10), others=q?[]:allParties.slice(10);
  let dims=[...dimTotals.keys()];
  if(cfg.dim==='channel'){const o=['Auction Sale','Direct Export','Local Sale','Local Roast'];dims.sort((a,b)=>(o.indexOf(a)<0?999:o.indexOf(a))-(o.indexOf(b)<0?999:o.indexOf(b)));}
  else dims.sort((a,b)=>dimTotals.get(b).kg-dimTotals.get(a).kg);
  current={cfg,allParties,filtered,top,others,dims,partyTotals,cells,q};
 }

 function row(p,label,cls=''){
  const {dims,partyTotals,cells}=current,pt=partyTotals.get(p)||{kg:0,val:0};
  let h=`<tr class="${cls}"><td>${label}</td><td title="${esc(p)}">${esc(p)}</td>`;
  dims.forEach(d=>{const c=cells.get(p+'\x1f'+d)||{kg:0,val:0};h+=`<td>${fmt(c.kg,3)}</td><td>${fmt(c.val,2)}</td>`});
  return h+`<td class="pivot-total">${fmt(pt.kg,3)}</td><td class="pivot-total">${fmt(pt.val,2)}</td></tr>`;
 }
 function aggregate(parties){
  const a={kg:0,val:0,by:{}};
  current.dims.forEach(d=>a.by[d]={kg:0,val:0});
  parties.forEach(p=>{const pt=current.partyTotals.get(p)||{kg:0,val:0};a.kg+=pt.kg;a.val+=pt.val;current.dims.forEach(d=>{const c=current.cells.get(p+'\x1f'+d)||{kg:0,val:0};a.by[d].kg+=c.kg;a.by[d].val+=c.val})});
  return a;
 }
 function aggRow(name,a,cls=''){
  let h=`<tr class="${cls}"><td></td><td>${esc(name)}</td>`;
  current.dims.forEach(d=>h+=`<td>${fmt(a.by[d].kg,3)}</td><td>${fmt(a.by[d].val,2)}</td>`);
  return h+`<td>${fmt(a.kg,3)}</td><td>${fmt(a.val,2)}</td></tr>`;
 }
 function draw(){
  build();const {cfg,top,others,dims,q,filtered,allParties}=current;
  let h=`<table id="tcPivotExportTable" class="tc-pivot-table"><thead><tr><th rowspan="2">#</th><th rowspan="2">${esc(cfg.partyLabel)}</th>`;
  dims.forEach(d=>h+=`<th colspan="2">${esc(d)}</th>`);h+='<th colspan="2">Total</th></tr><tr>';
  dims.forEach(()=>h+='<th>Kg</th><th>Value USD</th>');h+='<th>Kg</th><th>Value USD</th></tr></thead><tbody>';
  top.forEach((p,i)=>h+=row(p,i+1));
  if(!q&&others.length){
   const a=aggregate(others);
   h+=`<tr id="tcOtherToggle" class="tc-other-row"><td>${expanded?'−':'+'}</td><td class="tc-expand">Other (${others.length} ${cfg.partyLabel.toLowerCase()}${others.length===1?'':'s'})</td>`;
   dims.forEach(d=>h+=`<td>${fmt(a.by[d].kg,3)}</td><td>${fmt(a.by[d].val,2)}</td>`);
   h+=`<td>${fmt(a.kg,3)}</td><td>${fmt(a.val,2)}</td></tr>`;
   if(expanded)others.forEach((p,i)=>h+=row(p,11+i,'tc-detail-row'));
  }
  if(q&&!filtered.length)h+=`<tr><td colspan="${4+dims.length*2}" style="text-align:center">No matching ${esc(cfg.partyLabel.toLowerCase())} found.</td></tr>`;
  h+='</tbody><tfoot>'+aggRow(q?`Filtered Total (${filtered.length})`:'Overall Total',aggregate(q?filtered:allParties),'tc-overall-row')+'</tfoot></table>';
  box.innerHTML=h;
  status.textContent=q?`${filtered.length} matching ${cfg.partyLabel.toLowerCase()} record(s) · export will use the filtered result.`:`Showing Top ${Math.min(10,allParties.length)} of ${allParties.length} ${cfg.partyLabel.toLowerCase()} records · ${others.length} other${others.length===1?'':'s'}.`;
  document.getElementById('tcOtherToggle')?.addEventListener('click',()=>{expanded=!expanded;draw()});
 }
 sel.addEventListener('change',()=>{expanded=false;if(search)search.value='';draw()});
 search?.addEventListener('input',()=>{expanded=false;draw()});
 draw();

 if(exportBtn&&exportMenu){
  exportBtn.addEventListener('click',e=>{e.stopPropagation();exportMenu.classList.toggle('show')});
  document.addEventListener('click',()=>exportMenu.classList.remove('show'));
  const exportTable=()=>document.getElementById('tcPivotExportTable');
  const fname=ext=>`Clean_Coffee_${sel.value}_${search?.value?'Filtered':'Top10'}_<?=preg_replace('/[^0-9A-Za-z_-]/','_', $season)?>.${ext}`;
  function xlsx(){
   const table=exportTable();if(!table||!window.XLSX)return;
   const wb=XLSX.utils.table_to_book(table,{sheet:'Analysis',raw:true});
   const ws=wb.Sheets.Analysis,range=XLSX.utils.decode_range(ws['!ref']);
   for(let r=2;r<=range.e.r;r++)for(let c=2;c<=range.e.c;c++){const a=XLSX.utils.encode_cell({r,c}),cell=ws[a];if(!cell)continue;const n=Number(String(cell.v).replace(/,/g,''));if(Number.isFinite(n)){cell.v=n;cell.t='n';cell.z='#,##0.00####';}}
   XLSX.writeFile(wb,fname('xlsx'));
  }
  function pdf(){
   const table=exportTable();if(!table||!window.jspdf)return;const {jsPDF}=window.jspdf,doc=new jsPDF({orientation:'landscape',unit:'mm',format:'a4'});
   doc.setFontSize(11);doc.text('Clean Coffee Buyer / Supplier-Seller Analysis',10,10);
   doc.setFontSize(7);doc.text(`Sale Season <?=htmlspecialchars($season)?> · ${sel.options[sel.selectedIndex].text}${search?.value?' · Filter: '+search.value:''}`,10,15);
   doc.autoTable({html:table,startY:19,theme:'grid',styles:{fontSize:4.8,cellPadding:.8},headStyles:{fontStyle:'bold'},footStyles:{fontStyle:'bold'}});
   doc.save(fname('pdf'));
  }
  function word(){
   const table=exportTable();if(!table)return;const clone=table.cloneNode(true);clone.querySelectorAll('th,td').forEach(c=>c.style.cssText='border:1px solid #555;padding:3px;font-family:Arial;font-size:8pt');clone.style.cssText='border-collapse:collapse;width:100%';
   const html=`<html><head><meta charset="utf-8"></head><body><h3>Clean Coffee Buyer / Supplier-Seller Analysis</h3><p>Sale Season <?=htmlspecialchars($season)?> · ${esc(sel.options[sel.selectedIndex].text)}${search?.value?' · Filter: '+esc(search.value):''}</p>${clone.outerHTML}</body></html>`;
   const b=new Blob(['\ufeff',html],{type:'application/msword'}),a=document.createElement('a');a.href=URL.createObjectURL(b);a.download=fname('doc');a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500);
  }
  exportMenu.addEventListener('click',e=>{const f=e.target.dataset.format;if(!f)return;e.stopPropagation();exportMenu.classList.remove('show');f==='xlsx'?xlsx():f==='pdf'?pdf():word()});
 }
})();
</script>

<script>
(function(){
 const btn=document.getElementById('tcExportBtn'),menu=document.getElementById('tcExportMenu'),table=document.getElementById('totalCleanSalesTable');
 if(!btn||!menu||!table)return;
 const season=<?=json_encode($season)?>;
 const safe=s=>String(s).replace(/[^A-Za-z0-9_-]+/g,'_');
 const filename=ext=>`Coffee_Sales_Summary_${safe(season)}.${ext}`;
 btn.addEventListener('click',e=>{e.stopPropagation();menu.classList.toggle('show')});
 document.addEventListener('click',()=>menu.classList.remove('show'));

 function matrix(){
   return [...table.rows].map(r=>[...r.cells].map(c=>c.innerText.trim()));
 }
 function numeric(v,percent=false){
   if(v===''||v==='-')return null;
   const n=Number(String(v).replace(/,/g,'').replace(/%/g,'').trim());
   return Number.isFinite(n)?(percent?n/100:n):v;
 }
 function exportExcel(){
   if(!window.XLSX){alert('Excel export library is not available.');return}
   const aoa=matrix();
   const ws=XLSX.utils.aoa_to_sheet(aoa);
   const range=XLSX.utils.decode_range(ws['!ref']);
   // Rows 3 onward contain data. First column is text; all remaining populated cells are numeric.
   for(let r=2;r<=range.e.r;r++){
     for(let c=1;c<=range.e.c;c++){
       const a=XLSX.utils.encode_cell({r,c}),cell=ws[a];
       if(!cell||cell.v==='')continue;
       const isPct=(c===range.e.c)||(aoa[r]&&aoa[r][0]==='Channel Share'&&(c===1||c===4||c===7||c===10));
       const n=numeric(cell.v,isPct);
       if(typeof n==='number'){cell.v=n;cell.t='n';cell.z=isPct?'0.00%':'#,##0.00####';}
     }
   }
   ws['!cols']=[{wch:18},...Array(15).fill({wch:12})];
   const wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,ws,'Coffee Sales Summary');
   XLSX.writeFile(wb,filename('xlsx'),{cellStyles:true});
 }
 function exportPDF(){
   if(!window.jspdf||!window.jspdf.jsPDF){alert('PDF export library is not available.');return}
   const {jsPDF}=window.jspdf,doc=new jsPDF({orientation:'landscape',unit:'mm',format:'a4'});
   doc.setFont('helvetica','bold');doc.setFontSize(13);doc.text('Coffee Sales Summary',14,13);
   doc.setFont('helvetica','normal');doc.setFontSize(8);doc.text(`Clean coffee · Sale Season ${season}`,14,18);
   doc.autoTable({html:'#totalCleanSalesTable',startY:22,theme:'grid',
     styles:{fontSize:5.7,cellPadding:1.2,textColor:[40,31,27],lineColor:[91,64,51],lineWidth:.15,fillColor:false},
     headStyles:{fontStyle:'bold',textColor:[58,39,30],fillColor:[245,240,236],lineWidth:.25},
     footStyles:{fontStyle:'bold',textColor:[58,39,30],fillColor:[250,247,245],lineWidth:.25},
     columnStyles:{0:{cellWidth:24,halign:'left'}},
     didParseCell:d=>{if(d.column.index>0)d.cell.styles.halign='right';}
   });
   doc.save(filename('pdf'));
 }
 function exportWord(){
   const cloned=table.cloneNode(true);
   cloned.querySelectorAll('th,td').forEach(c=>c.setAttribute('style','border:1px solid #5b4033;padding:4px;font-family:Arial;font-size:9pt;'));
   cloned.setAttribute('style','border-collapse:collapse;width:100%;');
   const html=`<!doctype html><html><head><meta charset="utf-8"><title>Coffee Sales Summary</title></head><body><h2 style="font-family:Arial;color:#4b2e20;margin-bottom:3px">Coffee Sales Summary</h2><div style="font-family:Arial;font-size:9pt;margin-bottom:10px">Clean coffee · Sale Season ${season}</div>${cloned.outerHTML}</body></html>`;
   const blob=new Blob(['\ufeff',html],{type:'application/msword'});
   const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=filename('doc');document.body.appendChild(a);a.click();setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove()},500);
 }
 menu.addEventListener('click',e=>{const f=e.target.dataset.format;if(!f)return;e.stopPropagation();menu.classList.remove('show');if(f==='pdf')exportPDF();else if(f==='xlsx')exportExcel();else exportWord();});
})();
</script>

<script>
const auctionTrend=<?=json_encode(in_array($display,['sales','preauction','direct','totalclean'],true)?[]:$auctionTrend,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)?>,cleanMode=<?=json_encode($display==='clean')?>,ctx=document.getElementById('auctionTrendChart');
if(ctx&&window.Chart){const datasets=cleanMode?[
{type:'bar',label:'Quantity Sold (kg)',data:auctionTrend.map(r=>Number(r.qty)||0),yAxisID:'yQty',borderWidth:0,maxBarThickness:24},
{type:'line',label:'Weighted Avg Price (USD/50kg)',data:auctionTrend.map(r=>r.avg_price===null?null:Number(r.avg_price)),yAxisID:'yPrice',borderWidth:2,pointRadius:2,tension:.25}
]:[
{type:'bar',label:'Dry Cherry Qty (kg)',data:auctionTrend.map(r=>Number(r.dry_qty)||0),yAxisID:'yQty',borderWidth:0,maxBarThickness:18},
{type:'bar',label:'Clean Coffee Qty (kg)',data:auctionTrend.map(r=>Number(r.clean_qty)||0),yAxisID:'yQty',borderWidth:0,maxBarThickness:18},
{type:'line',label:'Dry Cherry Avg Price',data:auctionTrend.map(r=>r.dry_avg_price===null?null:Number(r.dry_avg_price)),yAxisID:'yPrice',borderWidth:2,pointRadius:2,tension:.25},
{type:'line',label:'Clean Coffee Avg Price',data:auctionTrend.map(r=>r.clean_avg_price===null?null:Number(r.clean_avg_price)),yAxisID:'yPrice',borderWidth:2,pointRadius:2,tension:.25}];
new Chart(ctx,{data:{labels:auctionTrend.map(r=>'A'+r.auction_no),datasets},options:{responsive:true,maintainAspectRatio:false,interaction:{mode:'index',intersect:false},plugins:{legend:{position:'top',labels:{boxWidth:9,boxHeight:9,font:{size:8},padding:8}}},scales:{x:{grid:{display:false},ticks:{font:{size:8},autoSkip:false},title:{display:true,text:'Auction No.',font:{size:8}}},yQty:{position:'left',beginAtZero:true,title:{display:true,text:'Quantity sold (kg)',font:{size:8}},ticks:{font:{size:8},callback:v=>Number(v).toLocaleString()}},yPrice:{position:'right',title:{display:true,text:cleanMode?'Avg. price (USD/50kg)':'Avg. price (TZS/kg)',font:{size:8}},grid:{drawOnChartArea:false},ticks:{font:{size:8},callback:v=>Number(v).toLocaleString()}}}}});}
</script>

<script>
(function(){
 const btn=document.getElementById('preExportBtn'),menu=document.getElementById('preExportMenu'),paper=document.getElementById('preAuctionReportPaper');
 if(!btn||!menu||!paper)return;
 btn.addEventListener('click',e=>{e.stopPropagation();menu.classList.toggle('show')});
 document.addEventListener('click',()=>menu.classList.remove('show'));
 const season=<?=json_encode($season??'')?>;
 const base='Pre_Auction_Report_'+String(season||'').replace('/','-');
 function word(){const html='<!doctype html><html><head><meta charset="utf-8"><style>body{font-family:Arial;font-size:10pt}h1{text-align:center;font-size:14pt}h2{font-size:12pt}h3{font-size:11pt}table{border-collapse:collapse;width:100%;margin:6px 0 14px}th,td{border:1px solid #555;padding:4px}th{background:#d9e8f6;text-align:center}td{text-align:right}td:first-child,td:nth-child(2){text-align:left}.gt{font-weight:bold}</style></head><body>'+paper.innerHTML.replace(/<div class="pre-export-bar"[\s\S]*?<\/div>\s*<\/div>/,'')+'</body></html>';const b=new Blob(['\ufeff',html],{type:'application/msword'}),a=document.createElement('a');a.href=URL.createObjectURL(b);a.download=base+'.doc';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
 function excel(){if(!window.XLSX){alert('Excel export library is not available.');return}const wb=XLSX.utils.book_new();paper.querySelectorAll('table').forEach((t,i)=>{const ws=XLSX.utils.table_to_sheet(t,{raw:true});XLSX.utils.book_append_sheet(wb,ws,'Table '+(i+1))});XLSX.writeFile(wb,base+'.xlsx')}
 async function pdf(){
  if(!window.html2canvas||!window.jspdf){alert('PDF export library is not available.');return}
  menu.classList.remove('show');
  const oldWidth=paper.style.width,oldMax=paper.style.maxWidth,oldShadow=paper.style.boxShadow;
  preApplyTableAlignment(paper);
  paper.classList.add('pdf-exporting');
  paper.style.width='794px';
  paper.style.maxWidth='794px';
  paper.style.boxShadow='none';
  try{
    if(document.fonts&&document.fonts.ready) await document.fonts.ready;
    const scale=Math.max(2.5,Math.min(3.2,(window.devicePixelRatio||1)*2));
    const canvas=await html2canvas(paper,{
      scale,
      backgroundColor:'#ffffff',
      useCORS:true,
      allowTaint:false,
      logging:false,
      imageTimeout:15000,
      removeContainer:true,
      scrollX:0,
      scrollY:-window.scrollY,
      windowWidth:794,
      onclone:doc=>{
        const p=doc.getElementById('preAuctionReportPaper');
        if(p){
          p.style.width='794px';
          p.style.maxWidth='794px';
          p.style.boxShadow='none';
          p.style.opacity='1';
          p.querySelectorAll('*').forEach(el=>{
            el.style.opacity='1';
            el.style.textShadow='none';
            el.style.filter='none';
          });
        }
      },
      ignoreElements:e=>e.classList&&e.classList.contains('pre-export-bar')
    });
    const {jsPDF}=window.jspdf;
    const doc=new jsPDF({orientation:'portrait',unit:'mm',format:'a4',compress:true,putOnlyUsedFonts:true});
    const margin=6,pw=doc.internal.pageSize.getWidth()-margin*2,ph=doc.internal.pageSize.getHeight()-margin*2;
    const pagePx=Math.floor(canvas.width*(ph/pw));
    let y=0,page=0;
    while(y<canvas.height){
      const hpx=Math.min(pagePx,canvas.height-y);
      const slice=document.createElement('canvas');
      slice.width=canvas.width;
      slice.height=hpx;
      const ctx=slice.getContext('2d',{alpha:false});
      ctx.fillStyle='#ffffff';
      ctx.fillRect(0,0,slice.width,slice.height);
      ctx.drawImage(canvas,0,y,canvas.width,hpx,0,0,canvas.width,hpx);
      if(page++) doc.addPage();
      const hmm=hpx*pw/canvas.width;
      /* PNG is lossless and avoids the faded/soft JPEG text seen previously. */
      doc.addImage(slice.toDataURL('image/png'),'PNG',margin,margin,pw,hmm,undefined,'FAST');
      y+=hpx;
    }
    doc.save(base+'.pdf');
  }finally{
    paper.classList.remove('pdf-exporting');
    paper.style.width=oldWidth;
    paper.style.maxWidth=oldMax;
    paper.style.boxShadow=oldShadow;
  }
 }
 menu.addEventListener('click',e=>{const f=e.target.dataset.format;if(!f)return;e.stopPropagation();menu.classList.remove('show');if(f==='pdf')pdf();else if(f==='xlsx')excel();else word()});
})();

function preApplyTableAlignment(root){
  root=root||document;
  root.querySelectorAll('.pre-report table').forEach(table=>{
    table.querySelectorAll('th').forEach(cell=>{
      cell.classList.remove('pre-text-cell','pre-number-cell');
      cell.classList.add('pre-header-cell');
    });
    table.querySelectorAll('td').forEach(cell=>{
      cell.classList.remove('pre-text-cell','pre-number-cell','pre-header-cell');
      const raw=(cell.textContent||'').replace(/\u00a0/g,' ').trim();
      const cleaned=raw.replace(/,/g,'').replace(/\s+/g,' ');
      // Numeric if cell consists of a number/currency-number/ dash only.
      const numeric=/^(?:[-–—]|(?:USD|TZS|\$)?\s*[-+]?\d+(?:\.\d+)?(?:\s*(?:kg|kgs|mt|usd|tzs))?)$/i.test(cleaned);
      cell.classList.add(numeric?'pre-number-cell':'pre-text-cell');
    });
  });
}
document.addEventListener('DOMContentLoaded',()=>preApplyTableAlignment(document));
</script>
<style id="sales-slide-fixed-layout">
#salesDashboardDocument.sales-ppt{position:relative!important;width:100%!important;max-width:1023px!important;aspect-ratio:1023/1447!important;height:auto!important;min-height:0!important;margin:0 auto!important;overflow:hidden!important;background-image:url("data:image/png;base64,")!important;background-position:center!important;background-size:100% 100%!important;background-repeat:no-repeat!important;box-shadow:0 4px 20px #0002!important}
#salesDashboardDocument .sales-ppt-header,#salesDashboardDocument .sales-ppt-title,#salesDashboardDocument .sales-ppt-footer{display:none!important}
#salesDashboardDocument .sales-ppt-body{position:absolute!important;top:21.6%!important;left:15px!important;width:993px!important;max-width:none!important;box-sizing:border-box!important;height:auto!important;overflow:visible!important;padding:0!important;margin:0!important;background:transparent!important;transform-origin:top left!important}
#salesDashboardDocument .sales-meta,#salesDashboardDocument .sales-table{width:100%!important;min-width:0!important;table-layout:fixed!important;border-collapse:collapse!important;background:rgba(255,255,255,.79)!important;margin:0 0 5px!important}
#salesDashboardDocument .sales-meta th,#salesDashboardDocument .sales-meta td,#salesDashboardDocument .sales-table th,#salesDashboardDocument .sales-table td{font-size:11.5px!important;line-height:1.18!important;padding:3px 5px!important;border:1px solid #685d50!important;white-space:nowrap!important;overflow-wrap:normal!important;word-break:normal!important;box-sizing:border-box!important;overflow:hidden!important;text-overflow:clip!important}
#salesDashboardDocument .sales-table th{text-align:center!important}
#salesDashboardDocument .sales-table td.sales-label{text-align:left!important}
#salesDashboardDocument .sales-table td.sales-num{text-align:center!important;font-variant-numeric:tabular-nums!important}
#salesDashboardDocument .sales-table th:first-child{width:29%!important}
#salesDashboardDocument .sales-table th:nth-child(2){width:15%!important}
#salesDashboardDocument .sales-table th:nth-child(3){width:19%!important}
#salesDashboardDocument .sales-table th:nth-child(4){width:16%!important}
#salesDashboardDocument .sales-table th:nth-child(5){width:21%!important}
#salesDashboardDocument .sales-band td,#salesDashboardDocument .sales-grand td{background:rgba(217,171,121,.72)!important;font-weight:bold!important}
/* PowerPoint reference: fine dark grid, clear cells, orange market/production bands. */
#salesDashboardDocument .sales-meta,#salesDashboardDocument .sales-table{background:transparent!important;border:1px solid #45413c!important;margin-bottom:3px!important}
#salesDashboardDocument .sales-meta th,#salesDashboardDocument .sales-meta td,#salesDashboardDocument .sales-table th,#salesDashboardDocument .sales-table td{border:1px solid #45413c!important;background:rgba(255,255,255,.12)!important;color:#191512!important;line-height:1.1!important;padding:2px 4px!important}
#salesDashboardDocument .sales-meta th,#salesDashboardDocument .sales-table th{font-weight:800!important;background:rgba(242,235,226,.35)!important}
#salesDashboardDocument .sales-table tr.sales-band td{background:rgba(238,139,60,.90)!important;font-weight:800!important;text-align:left!important}
#salesDashboardDocument .sales-table tr.sales-grand td{background:rgba(247,236,223,.68)!important;font-weight:800!important}
#salesDashboardDocument .sales-table tr.sales-production td{background:rgba(246,237,226,.50)!important;font-weight:800!important;font-style:italic!important}
#salesDashboardDocument .sales-table tr:not(.sales-band) td.sales-label{background:rgba(255,255,255,.05)!important}
#salesDashboardDocument .sales-table td.sales-num{white-space:nowrap!important;text-align:center!important}
#salesExportOptions[hidden],#salesProgress[hidden]{display:none!important}
@media print{#salesDashboardDocument{box-shadow:none!important}.sales-actions,.sales-progress{display:none!important}}

/* Live, selectable header and footer text; no typography depends on background pixels. */
#salesDashboardDocument .sales-ppt-header{display:flex!important;position:absolute!important;top:2.6%!important;left:19%!important;width:62%!important;height:11.3%!important;align-items:center!important;justify-content:center!important;background:none!important;z-index:2!important}
#salesDashboardDocument .gov-title{font-family:Arial,sans-serif!important;font-size:24px!important;font-weight:800!important;line-height:1.9!important;color:#984307!important;text-align:center!important;white-space:nowrap!important}
#salesDashboardDocument .sales-ppt-title{display:block!important;position:absolute!important;top:17.2%!important;left:0!important;width:100%!important;height:auto!important;text-align:center!important;font:bold 42px/1.15 Arial,sans-serif!important;color:#984307!important;white-space:nowrap!important;z-index:2!important;background:none!important}
#salesDashboardDocument .sales-ppt-footer{display:block!important;position:absolute!important;inset:0!important;pointer-events:none!important;background:none!important;z-index:2!important}
#salesDashboardDocument .sales-ppt-footer .contact{position:absolute!important;color:#fff!important;font:23px/1.15 Arial,sans-serif!important;white-space:nowrap!important;text-shadow:0 1px 2px #74401b!important}
#salesDashboardDocument .sales-ppt-footer .web{left:10%!important;top:86.0%!important}
#salesDashboardDocument .sales-ppt-footer .email{left:10%!important;top:89.6%!important}
#salesDashboardDocument .sales-ppt-footer .phone{left:10%!important;top:93.2%!important}
#salesDashboardDocument .sales-ppt-footer .social{left:76%!important;top:89.3%!important}
/* PowerPoint/PDF reference: bold underline and icon-aligned, live footer labels.
   Coordinates are percentages of the complete A4 dashboard, not the footer strip. */
#salesDashboardDocument .sales-ppt-title span{display:inline-block!important;border-bottom:7px solid #9d704a!important;padding:0 4px 2px!important;line-height:1.08!important;text-decoration:none!important}
#salesDashboardDocument .sales-ppt-footer .contact{left:auto!important;right:auto!important;bottom:auto!important;display:block!important;position:absolute!important;max-width:none!important;overflow:visible!important;white-space:nowrap!important;word-break:normal!important;font:23px/1.2 Arial,sans-serif!important;color:#fff!important}
#salesDashboardDocument .sales-ppt-footer .web{left:10.2%!important;top:85.55%!important}
#salesDashboardDocument .sales-ppt-footer .email{left:10.2%!important;top:89.05%!important}
#salesDashboardDocument .sales-ppt-footer .phone{left:10.2%!important;top:92.6%!important}
#salesDashboardDocument .sales-ppt-footer .social{left:76.3%!important;top:89.05%!important}

#salesDashboardDocument .sales-table tr.sales-band td{background:rgba(238,139,60,.90)!important}
#salesDashboardDocument .sales-table tr.sales-grand td{background:rgba(247,236,223,.68)!important}

/* 2026-10-08: fix the containing block of every footer label.
   Old responsive .sales-ppt-footer height:auto!important caused labels to overlap tables. */
#salesDashboardDocument.sales-ppt .sales-ppt-footer{
 position:absolute!important;inset:0!important;top:0!important;left:0!important;
 right:0!important;bottom:0!important;width:100%!important;height:100%!important;
 min-height:0!important;aspect-ratio:auto!important;margin:0!important;
 padding:0!important;border:0!important;box-sizing:border-box!important;
 background:none!important;background-image:none!important;
 overflow:visible!important;z-index:5!important;pointer-events:none!important;
}
#salesDashboardDocument.sales-ppt .sales-ppt-footer .contact{
 position:absolute!important;display:block!important;white-space:nowrap!important;
 font-family:Arial,sans-serif!important;font-size:22px!important;
 line-height:1.15!important;font-weight:700!important;
 color:#fff!important;text-shadow:0 2px 3px rgba(71,37,12,.9)!important;
 margin:0!important;padding:0!important;transform:none!important;
}
#salesDashboardDocument.sales-ppt .sales-ppt-footer .web{left:9.2%!important;top:83.85%!important}
#salesDashboardDocument.sales-ppt .sales-ppt-footer .email{left:9.2%!important;top:87.4%!important}
#salesDashboardDocument.sales-ppt .sales-ppt-footer .phone{left:9.2%!important;top:91.15%!important}
#salesDashboardDocument.sales-ppt .sales-ppt-footer .social{left:76.2%!important;top:86.6%!important;font-size:21px!important}
#salesDashboardDocument.sales-ppt .sales-ppt-title span{border-bottom:8px solid #985027!important}

/* Allow the two long grand-total descriptions to wrap within column one. */
#salesDashboardDocument .sales-table tr.sales-grand td.sales-grand-label{
  white-space:normal!important;
  overflow-wrap:break-word!important;
  word-break:normal!important;
  overflow:visible!important;
  text-overflow:clip!important;
  height:auto!important;
  line-height:1.25!important;
  vertical-align:middle!important;
  text-align:left!important;
}
#salesDashboardDocument .sales-table tr.sales-grand{height:auto!important;}
</style>
<script>
(function(){
const paper=document.getElementById('salesDashboardDocument');if(!paper)return;
const body=paper.querySelector('.sales-ppt-body');
function fit(){if(!body)return;const width=paper.getBoundingClientRect().width||1023;const height=width*1447/1023;const areaHeight=height*.424;body.style.transform='none';const natural=body.scrollHeight||1;const factor=Math.min(width/1023,areaHeight/natural);body.style.transform='scale('+Math.max(.01,factor)+')';}
window.salesDashboardFit=fit;window.addEventListener('resize',fit,{passive:true});if(window.ResizeObserver)new ResizeObserver(fit).observe(paper);document.fonts?.ready.then(fit);requestAnimationFrame(fit);
const button=document.getElementById('salesExportButton'),menu=document.getElementById('salesExportOptions'),progress=document.getElementById('salesProgress'),status=document.getElementById('salesProgressText'),bar=document.getElementById('salesProgressFill'),percent=document.getElementById('salesProgressPercent');
if(!button||!menu)return;
button.addEventListener('click',e=>{e.stopPropagation();menu.hidden=!menu.hidden;});document.addEventListener('click',e=>{if(!e.target.closest('.sales-export-control'))menu.hidden=true;});
function update(n,msg){if(progress)progress.hidden=false;if(bar)bar.style.width=n+'%';if(percent)percent.textContent=n+'%';if(status)status.textContent=msg;}
function save(blob,name){const a=document.createElement('a'),u=URL.createObjectURL(blob);a.href=u;a.download=name;document.body.appendChild(a);a.click();setTimeout(()=>{URL.revokeObjectURL(u);a.remove()},5000);}
function base(){return 'TCB_Sales_Dashboard_'+String(<?=json_encode($season)?>).replace(/\W/g,'_');}
async function library(url,check){if(check())return;await new Promise((resolve,reject)=>{const s=document.createElement('script');s.src=url;s.onload=resolve;s.onerror=()=>reject(new Error('Could not load export library: '+url));document.head.appendChild(s);});if(!check())throw new Error('Export library unavailable');}
async function snapshot(){
 await library('https://cdnjs.cloudflare.com/ajax/libs/html2canvas/1.4.1/html2canvas.min.js',()=>!!window.html2canvas);
 if(document.fonts?.ready)await document.fonts.ready;
 update(40,'Rendering full-resolution A4 dashboard…');
 const canvas=await html2canvas(paper,{
  scale:2.5,useCORS:true,allowTaint:false,backgroundColor:'#ffffff',logging:false,
  width:1023,height:1447,windowWidth:1200,windowHeight:1600,scrollX:0,scrollY:0,
  onclone:doc=>{
   const p=doc.getElementById('salesDashboardDocument');
   // Move the page out of responsive dashboard wrappers, which otherwise clip the PDF.
   doc.body.appendChild(p);
   p.style.setProperty('position','absolute','important');
   p.style.setProperty('top','0','important');
   p.style.setProperty('left','0','important');
   p.style.setProperty('width','1023px','important');
   p.style.setProperty('min-width','1023px','important');
   p.style.setProperty('max-width','1023px','important');
   p.style.setProperty('height','1447px','important');
   p.style.setProperty('aspect-ratio','auto','important');
   p.style.setProperty('margin','0','important');
   p.style.setProperty('box-shadow','none','important');
   p.style.setProperty('overflow','hidden','important');
   const b=p.querySelector('.sales-ppt-body');
   if(b){
    b.style.setProperty('width','993px','important');
    b.style.setProperty('left','15px','important');
    b.style.setProperty('top','21.6%','important');
    b.style.setProperty('transform','none','important');
    const natural=b.scrollHeight||1;
    const scale=Math.min(1,1447*.424/natural);
    b.style.setProperty('transform','scale('+scale+')','important');
   }
  }
 });
 if(canvas.width<2000||canvas.height<3000)throw new Error('Export image dimensions are unexpectedly small');
 return canvas;
}
function canvasBlob(canvas,type,quality){return new Promise((resolve,reject)=>canvas.toBlob(b=>b?resolve(b):reject(new Error('Image encoding failed')),type,quality));}
function xmlEscape(s){return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');}
async function excelWithImage(canvas){
 await library('https://cdnjs.cloudflare.com/ajax/libs/xlsx/0.18.5/xlsx.full.min.js',()=>!!window.XLSX);
 await library('https://cdnjs.cloudflare.com/ajax/libs/jszip/3.10.1/jszip.min.js',()=>!!window.JSZip);
 update(65,'Creating Excel workbook with embedded dashboard image…');
 const wb=XLSX.utils.book_new();
 const ws=XLSX.utils.aoa_to_sheet([['TANZANIA COFFEE BOARD — SALES DASHBOARD'],['Dashboard image is embedded below. Editable source tables are in the following sheets.']]);
 ws['!cols']=[{wch:100}];XLSX.utils.book_append_sheet(wb,ws,'Dashboard');
 paper.querySelectorAll('table').forEach((t,i)=>XLSX.utils.book_append_sheet(wb,XLSX.utils.table_to_sheet(t,{raw:true}),'Data '+(i+1)));
 const bytes=XLSX.write(wb,{bookType:'xlsx',type:'array'});
 const zip=await JSZip.loadAsync(bytes);
 const image=await canvasBlob(canvas,'image/png');zip.file('xl/media/dashboard.png',image);
 const sheet='xl/worksheets/sheet1.xml';let sheetXml=await zip.file(sheet).async('string');
 sheetXml=sheetXml.replace('</worksheet>','<drawing r:id="rIdDashboard" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"/></worksheet>');zip.file(sheet,sheetXml);
 const relPath='xl/worksheets/_rels/sheet1.xml.rels';let rel=zip.file(relPath)?await zip.file(relPath).async('string'):'<'+'?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"></Relationships>';
 rel=rel.replace('</Relationships>','<Relationship Id="rIdDashboard" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/drawing" Target="../drawings/drawing1.xml"/></Relationships>');zip.file(relPath,rel);
 const cx=1023*9525,cy=1447*9525;
 zip.file('xl/drawings/drawing1.xml','<'+'?xml version="1.0" encoding="UTF-8" standalone="yes"?><xdr:wsDr xmlns:xdr="http://schemas.openxmlformats.org/drawingml/2006/spreadsheetDrawing" xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main"><xdr:oneCellAnchor><xdr:from><xdr:col>0</xdr:col><xdr:colOff>0</xdr:colOff><xdr:row>3</xdr:row><xdr:rowOff>0</xdr:rowOff></xdr:from><xdr:ext cx="'+cx+'" cy="'+cy+'"/><xdr:pic><xdr:nvPicPr><xdr:cNvPr id="1" name="Sales Dashboard"/><xdr:cNvPicPr/></xdr:nvPicPr><xdr:blipFill><a:blip xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships" r:embed="rIdImage1"/><a:stretch><a:fillRect/></a:stretch></xdr:blipFill><xdr:spPr><a:xfrm><a:off x="0" y="0"/><a:ext cx="'+cx+'" cy="'+cy+'"/></a:xfrm><a:prstGeom prst="rect"><a:avLst/></a:prstGeom></xdr:spPr></xdr:pic><xdr:clientData/></xdr:oneCellAnchor></xdr:wsDr>');
 zip.file('xl/drawings/_rels/drawing1.xml.rels','<'+'?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rIdImage1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/image" Target="../media/dashboard.png"/></Relationships>');
 let ct=await zip.file('[Content_Types].xml').async('string');
 if(!ct.includes('Extension="png"'))ct=ct.replace('</Types>','<Default Extension="png" ContentType="image/png"/></Types>');
 ct=ct.replace('</Types>','<Override PartName="/xl/drawings/drawing1.xml" ContentType="application/vnd.openxmlformats-officedocument.drawing+xml"/></Types>');zip.file('[Content_Types].xml',ct);
 save(await zip.generateAsync({type:'blob',compression:'DEFLATE'}),base()+'.xlsx');
}
async function wordWithImage(canvas){
 await library('https://cdnjs.cloudflare.com/ajax/libs/jszip/3.10.1/jszip.min.js',()=>!!window.JSZip);
 update(75,'Creating a genuine Word DOCX document…');
 const png=await canvasBlob(canvas,'image/png');
 const zip=new JSZip();
 const cx=5486400,cy=Math.round(cx*1447/1023);
 const xml='<'+'?xml version="1.0" encoding="UTF-8" standalone="yes"?>';
 zip.file('[Content_Types].xml',xml+'<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Default Extension="png" ContentType="image/png"/><Override PartName="/word/document.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml"/></Types>');
 zip.file('_rels/.rels',xml+'<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="word/document.xml"/></Relationships>');
 zip.file('word/_rels/document.xml.rels',xml+'<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rIdImage1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/image" Target="media/dashboard.png"/></Relationships>');
 zip.file('word/media/dashboard.png',png);
 const drawing='<w:drawing><wp:inline distT="0" distB="0" distL="0" distR="0"><wp:extent cx="'+cx+'" cy="'+cy+'"/><wp:docPr id="1" name="Tanzania Coffee Board Sales Dashboard"/><a:graphic xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main"><a:graphicData uri="http://schemas.openxmlformats.org/drawingml/2006/picture"><pic:pic xmlns:pic="http://schemas.openxmlformats.org/drawingml/2006/picture"><pic:nvPicPr><pic:cNvPr id="0" name="Dashboard"/><pic:cNvPicPr/></pic:nvPicPr><pic:blipFill><a:blip xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships" r:embed="rIdImage1"/><a:stretch><a:fillRect/></a:stretch></pic:blipFill><pic:spPr><a:xfrm><a:off x="0" y="0"/><a:ext cx="'+cx+'" cy="'+cy+'"/></a:xfrm><a:prstGeom prst="rect"><a:avLst/></a:prstGeom></pic:spPr></pic:pic></a:graphicData></a:graphic></wp:inline></w:drawing>';
 const document=xml+'<w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main" xmlns:wp="http://schemas.openxmlformats.org/drawingml/2006/wordprocessingDrawing" xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main" xmlns:pic="http://schemas.openxmlformats.org/drawingml/2006/picture" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><w:body><w:p><w:pPr><w:jc w:val="center"/><w:spacing w:before="0" w:after="0"/></w:pPr><w:r>'+drawing+'</w:r></w:p><w:sectPr><w:pgSz w:w="11906" w:h="16838"/><w:pgMar w:top="180" w:right="180" w:bottom="180" w:left="180" w:header="0" w:footer="0" w:gutter="0"/></w:sectPr></w:body></w:document>';
 zip.file('word/document.xml',document);
 save(await zip.generateAsync({type:'blob',compression:'DEFLATE'}),base()+'.docx');
}
menu.addEventListener('click',async e=>{
 const type=e.target.closest('[data-type]')?.dataset.type;if(!type)return;
 e.stopPropagation();menu.hidden=true;button.disabled=true;update(5,'Preparing dashboard export…');
 try{
  const canvas=await snapshot();
  if(type==='png'||type==='jpg'){update(85,'Encoding image…');save(await canvasBlob(canvas,type==='png'?'image/png':'image/jpeg',.96),base()+'.'+type);}
  else if(type==='pdf'){
   await library('https://cdnjs.cloudflare.com/ajax/libs/jspdf/2.5.1/jspdf.umd.min.js',()=>!!window.jspdf?.jsPDF);
   update(85,'Composing PDF…');const pdf=new jspdf.jsPDF({orientation:'portrait',unit:'mm',format:'a4',compress:true});pdf.addImage(canvas.toDataURL('image/png'),'PNG',0,0,210,297);pdf.save(base()+'.pdf');
  }else if(type==='xlsx')await excelWithImage(canvas);
  else if(type==='doc')await wordWithImage(canvas);
  update(100,'Export completed');
 }catch(err){update(0,'Export failed');alert('Dashboard export failed: '+err.message);console.error(err);}
 finally{button.disabled=false;setTimeout(()=>{if(progress)progress.hidden=true;},2200);}
});
})();
</script>
</body>
</html>
